package com.citacloud.app.models;
import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="historial_clinico") public class HistorialClinico { @Id @GeneratedValue private UUID id; @Column(name="empresa_id",nullable=false) private UUID empresaId; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="paciente_id",nullable=false) private Paciente paciente; private String alergias; private String antecedentes; private String resumen; @Column(name="actualizado_en") private LocalDateTime actualizadoEn=LocalDateTime.now(); public UUID getId(){return id;} public UUID getEmpresaId(){return empresaId;} public void setEmpresaId(UUID v){empresaId=v;} public Paciente getPaciente(){return paciente;} public void setPaciente(Paciente v){paciente=v;} public String getAlergias(){return alergias;} public void setAlergias(String v){alergias=v;} public String getAntecedentes(){return antecedentes;} public void setAntecedentes(String v){antecedentes=v;} public String getResumen(){return resumen;} public void setResumen(String v){resumen=v;} public LocalDateTime getActualizadoEn(){return actualizadoEn;} public void setActualizadoEn(LocalDateTime v){actualizadoEn=v;} }
